dofile((arg[0]:match("^(.*)/[^/]*$") or ".").."/common.lua")
local OLD=""
-- 1. an old v1.6.3 pattern, via the real flash path
pset_write(1,OLD)
fload()
check(pats[1]~=nil and #pats[1]==753,"old 753-byte pattern is accepted by fload")
ldp(1)
local ok=true
for t=1,4 do for p=4,16,4 do local k=p+t if ls[k]~=ls[t] or le[k]~=le[t] or dv2[k]~=dv2[t] then ok=false end end end
check(ok,"old pattern: note/octave/duration/ratchet inherit the trigger loop and division")
local altok=true
for t=1,4 do if ls[20+t]<1 or le[20+t]>16 or dv2[20+t]<1 then altok=false end end
check(altok,"old pattern: alt-note loop/division restored from its own saved bytes")
check(tsyn==0 and ndsy==false,"old pattern: division sync defaults to None")
gp(1) tap(15,7) advance(3) tap(15,7)
check(true,"old pattern plays")
-- 2. new pattern round trip through flash
gp(3) cfg(function() tap(11,6) end) gp(3) loop(1,3,1) tdiv(3,1)
svp(2) fsave(2)
local before=cap()
gp(1) cfg(function() tap(13,6) end) loop(1,16,1)
fload()
ldp(2)
check(cap()==before,"loop/division per parameter survive save to flash + load")
check(same("oct",1,1,3,3),"octave loop 1..3 /3 restored")

-- 3. loop snap on a non-trigger page
cfg(function() tap(11,6) end)
gp(1) loop(1,4,1)
cfg(function() tap(14,3) end)
check(lsnap==true,"loop snap on")
gp(3) loop(2,3,1)
check(psnap[1]~=nil and psnap[1][3]==3,"snap holds a pending octave loop")
local before_ls=ls[9]
gp(1) tap(15,7) advance(3) tap(15,7)
io.write("# snap state ",tostring(psnap[1]==nil)," ",ls[9]," ",le[9]," tr2=",tostring(tr2)," lc=",lc[1],"\n")
check(psnap[1]==nil and ls[9]==2 and le[9]==3,"snap applied octave loop at the next trigger-loop cycle")
check(ls[1]==1 and le[1]==4,"snap left the trigger loop alone")
io.write(fails==0 and "ALL PASS\n" or ("FAILS: "..fails.."\n"))
